{"language":"js","summary":"Survey repo layout to partition the audit","code":"const sh = async (c)=> (await Bun.$`sh -c ${c}`.nothrow().text());
const [pwd, top, git, files] = await Promise.all([
  sh('pwd'),
  sh('ls -la | head -50'),
  sh('git rev-parse --show-toplevel 2>&1; git log --oneline | head -3'),
  sh('git ls-files 2>/dev/null | sed -E "s/.*\\.//" | sort | uniq -c | sort -rn | head -15'),
]);
print(pwd, top, git, files);"}
